 async function load(){error='';loading=true;try{const [posts,d,s,g]=await Promise.all([api.get<{items:Item[];pagination:{total:number}}>('/posts?pageSize=5'),api.get<{pagination:{total:number}}>('/posts?draft=true&pageSize=1'),api.get<{items:unknown[]}>('/series'),api.get<{pendingPushCount:number}>('/git/status')]);total=posts.pagination.total;items=posts.items;drafts=d.pagination.total;series=s.items.length;pending=g.pendingPushCount;}catch(e){error=messageOf(e);}finally{loading=false;}}
 onMount(()=>{void load();});
